<?php
declare(strict_types=1);require __DIR__.'/app/request-distribution.php';header('Cache-Control: no-store, private');$destination='requests';
try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new DomainException('Use POST for distribution changes.',405);$user=require_verified();verify_csrf();$action=(string)($_POST['action']??'');$requestId=marketplace_text($_POST,'request_id',36,true);$destination='request-distribution?id='.rawurlencode($requestId);$pdo=db();$pdo->beginTransaction();if($action==='share.create'){$request=request_owned($user,$requestId);$type=$request['visibility']==='PUBLIC'?'PUBLIC':'PRIVATE_LINK';$link=request_share_create($user,$requestId,$type,null,$request['response_deadline']);$destination.='&share='.rawurlencode($link['token']);$message='Share link and request card are ready.';}elseif($action==='campaign.create'){$campaign=request_campaign_create($user,$requestId,$_POST);$request=request_owned($user,$requestId);$type=$request['visibility']==='PUBLIC'?'PUBLIC':'PRIVATE_LINK';$link=request_share_create($user,$requestId,$type,$campaign['id'],$request['response_deadline']);$destination.='&share='.rawurlencode($link['token']);$message='Distribution campaign started and attributed link created.';}elseif($action==='invitation.create'){$invite=request_invite_supplier($user,$requestId,$_POST);$destination.='&share='.rawurlencode($invite['token']);$message='Supplier invitation recorded. Copy and send the private invitation link.';}else throw new DomainException('Unknown distribution action.',422);$pdo->commit();flash('success',$message);redirect($destination);}catch(Throwable $error){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error',$error instanceof DomainException?$error->getMessage():'Distribution could not be updated.');redirect($destination);}
